use rei_microphysics::{StepControl};
use rei_microphysics::coupled_primary::{PrimaryState,PrimaryPacket,PrimaryStage,primary_stage_step};
use std::io::{self,Read};
fn e(s:&PrimaryState,f:f64)->f64{s.w_ev_per_h+13.598434599702*s.fractions[0]+f*(24.587389011*s.fractions[1]+(24.587389011+54.41776)*s.fractions[2])+s.escape_ev_per_h+s.packets.iter().map(|p|p.energy_ev*p.per_h).sum::<f64>()}
fn main(){let mut text=String::new();io::stdin().read_to_string(&mut text).unwrap();let mut tokens=text.split_whitespace();while let Some(label)=tokens.next(){let mut v=||tokens.next().unwrap().parse::<f64>().unwrap();let nh=v();let f=v();let h=v();let dt=v();let x=[v(),v(),v()];let w=v();let n=v() as usize;let packets=(0..n).map(|_|PrimaryPacket{energy_ev:v(),per_h:v()}).collect();let old=PrimaryState{fractions:x,w_ev_per_h:w,escape_ev_per_h:0.,packets};let stage=PrimaryStage{n_h_cm3:nh,f_he:f,h_mean_per_s:h};for tolerance in [1e-15,3e-16,2e-16,1e-16]{match primary_stage_step(&stage,&old,dt,StepControl{max_iterations:400,residual_tolerance:tolerance}){Ok(result)=>println!("{} {:.17e} OK {} {:.17e} {:.17e}",label,tolerance,result.iterations,result.residual,(e(&result.state,f)+result.events.thermal_work_ev_per_h-e(&old,f))/e(&old,f)),Err(error)=>println!("{} {:.17e} FAIL {:?}",label,tolerance,error)}}}}
